Show-Note 'Module 4 : le pare-feu deploye par CloudFormation'
Show-Cmd 'aws network-firewall describe-firewall --firewall-name nfw-prod-leman-TP-AC --query "[Firewall.FirewallName,FirewallStatus.Status]" --output text'
Show-Note 'Depuis app-01 : un depot autorise, puis un site bloque'
Show-Cmd 'ssm app-01 "curl -sS -m 10 -o /dev/null -w ''HTTP %{http_code}'' https://cdn.amazonlinux.com/"'
Show-Cmd 'ssm app-01 "curl -sS -m 10 -o /dev/null -w ''HTTP %{http_code}'' https://example.com/ 2>&1; echo"'
Show-Shot 'm04-1'
Clear-Host
Show-Note 'Le flux bloque est dans le journal des alertes'
Show-Cmd '(aws logs filter-log-events --log-group-name /leman/nfw-alert-TP-AC --start-time ([DateTimeOffset]::UtcNow.AddMinutes(-10).ToUnixTimeMilliseconds()) --output json | ConvertFrom-Json).events | Select-Object -Last 2 | ForEach-Object { $e = ($_.message | ConvertFrom-Json).event; "{0} -> {1}:{2}  {3}  {4}" -f $e.src_ip, $e.dest_ip, $e.dest_port, $e.alert.action, $e.alert.signature }'
Show-Note 'Le flux autorise est dans le journal des flux'
Show-Cmd '(aws logs filter-log-events --log-group-name /leman/nfw-flow-TP-AC --filter-pattern 10.20.1.10 --start-time ([DateTimeOffset]::UtcNow.AddMinutes(-10).ToUnixTimeMilliseconds()) --output json | ConvertFrom-Json).events | Select-Object -Last 2 | ForEach-Object { $e = ($_.message | ConvertFrom-Json).event; "{0} -> {1}:{2}  {3} octets" -f $e.src_ip, $e.dest_ip, $e.dest_port, $e.netflow.bytes }'
Show-Shot 'm04-2'
